const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const clinic_name = text(input.clinic_name);
const handoff_task_id = Number(input.handoff_task_id);
const action = text(input.action).toLowerCase();
const actor_name = text(input.actor_name);
const contact_channel = text(input.contact_channel || 'phone').toLowerCase();
const note = text(input.note);
const next_followup_minutes = Number(input.next_followup_minutes ?? 60);
const confirm_action = toBoolean(input.confirm_action);

const allowedActions = [
  'claim',
  'release',
  'mark_no_answer',
  'resolve_confirmed',
  'resolve_cancelled',
  'resolve_reschedule',
  'close_no_action',
];

const allowedChannels = [
  'phone',
  'whatsapp',
  'sms',
  'telegram',
  'email',
  'in_person',
  'other',
];

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!Number.isInteger(handoff_task_id) || handoff_task_id < 1) {
  errors.push({
    field: 'handoff_task_id',
    message: 'handoff_task_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (!allowedActions.includes(action)) {
  errors.push({
    field: 'action',
    message: 'action انتخاب‌شده معتبر نیست.',
  });
}

if (!actor_name) {
  errors.push({
    field: 'actor_name',
    message: 'نام کاربر یا منشی انجام‌دهنده الزامی است.',
  });
}

if (!allowedChannels.includes(contact_channel)) {
  errors.push({
    field: 'contact_channel',
    message: 'کانال تماس معتبر نیست.',
  });
}

if (note.length > 1000) {
  errors.push({
    field: 'note',
    message: 'یادداشت نباید بیشتر از 1000 کاراکتر باشد.',
  });
}

if (
  !Number.isInteger(next_followup_minutes) ||
  next_followup_minutes < 5 ||
  next_followup_minutes > 10080
) {
  errors.push({
    field: 'next_followup_minutes',
    message: 'زمان پیگیری بعدی باید بین 5 دقیقه و 7 روز باشد.',
  });
}

if (confirm_action !== true) {
  errors.push({
    field: 'confirm_action',
    message: 'اقدام منشی باید به‌صورت صریح تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    handoff_task_id,
    action,
    actor_name,
    contact_channel,
    note,
    next_followup_minutes,
    confirm_action,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

const db = $('Apply Human Handoff Action').first().json;

const hasError =
  Boolean($json.error) ||
  Boolean($json.errorMessage) ||
  $json.success === false;

return [{
  json: {
    ...db,
    calendar_sync_status:
      hasError ? 'delete_failed' : 'deleted',
    calendar_sync_message:
      hasError
        ? 'نوبت لغو شد، اما حذف رویداد Google Calendar نیاز به بررسی دارد.'
        : 'رویداد Google Calendar حذف شد.',
  },
}];

return [{
  json: {
    success: false,
    result: $json.result ?? 'handoff_action_failed',
    message: $json.message ?? 'اقدام روی تسک انجام نشد.',
    handoff_task_id: $json.handoff_task_id ?? null,
    appointment_id: $json.appointment_id ?? null,
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'اطلاعات اقدام منشی ناقص یا نامعتبر است.',
    errors: $json.errors ?? [],
  },
}];

const db = $('Apply Human Handoff Action').first().json;

return [{
  json: {
    ...db,
    calendar_sync_status: 'not_present',
    calendar_sync_message:
      'اقدام روی تسک انجام شد و رویدادی در Google Calendar برای حذف وجود نداشت.',
  },
}];
